 "content": "from collections import deque
from itertools import permutations


def transform(grid):
    """Fill outlined rectangles with checkerboards keyed by the loose-dot colors."""
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    frame_cells = set()

    # A frame is a connected monochrome component whose bounding box is a
    # one-cell rectangular ring, with an empty interior.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            r0 = min(rr for rr, _ in comp); r1 = max(rr for rr, _ in comp)
            c0 = min(cc for _, cc in comp); c1 = max(cc for _, cc in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(rr,cc) for rr in range(r0,r1+1) for cc in range(c0,c1+1)
                      if rr in (r0,r1) or cc in (c0,c1)}
            if set(comp) == border and all(grid[rr][cc] == color for rr,cc in border):
                frames.append((r0,r1,c0,c1,color))
                frame_cells.update(border)

    if not frames:
        return [row[:] for row in grid]

    # Count the loose colored dots. Their populations identify which color
    # belongs in each frame; match globally to avoid reusing a color.
    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r,c) not in frame_cells:
                counts[color] = counts.get(color, 0) + 1
    frame_colors = {f[4] for f in frames}
    candidates = [color for color in counts if color not in frame_colors]

    expected = []
    for r0,r1,c0,c1,_ in frames:
        expected.append(sum(1 for r in range(r0+1,r1) for c in range(c0+1,c1) if (r+c)%2 == 0))

    # Select the distinct loose-dot colors whose populations best match the
    # checkerboard cell counts.
    best = None
    for chosen in permutations(candidates, len(frames)):
        cost = sum(abs(counts[col] - need) for col,need in zip(chosen, expected))
        if best is None or cost < best[0]:
            best = (cost, chosen)
    if best is None:
        chosen = [0] * len(frames)
    else:
        chosen = best[1]

    out = [[0] * w for _ in range(h)]
    for i, (r0,r1,c0,c1,frame_color) in enumerate(frames):
        for c in range(c0,c1+1):
            out[r0][c] = out[r1][c] = frame_color
        for r in range(r0,r1+1):
            out[r][c0] = out[r][c1] = frame_color
        fill = chosen[i]
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c) % 2 == 0:
                    out[r][c] = fill
    return out
